// src/generator/snippet.ts
export async function generateSnippet(description: string): Promise<{ code: string; explanation: string }> {
  const response = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${process.env.AI_API_KEY}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'gpt-3.5-turbo', messages: [{ role: 'user', content: `Generate TypeScript code for: ${description}` }] }),
  });
  const data = await response.json();
  // Simplified parsing
  const content = data.choices[0].message.content;
  const [explanation, code] = content.split('---'); // Assume separator in response
  return { code: code.trim(), explanation: explanation.trim() };
}

// In CLI handler
program.command('generate <description>').option('--persist').action(async (description, options) => {
  const { code, explanation } = await generateSnippet(description);
  console.log('Explanation:', explanation);
  console.log('Code:\n', code);
  if (options.persist) {
    // Save to file or task...
    await Bun.write(`snippets/${crypto.randomUUID()}.ts`, code);
  }
});
```

